operations.text:
# PATCH_V3_GUARD_STATUS_BEGIN
try {
  $__tbot_v3_root = 'C:\alpaca-bot\ORG_BOT_UNIFIED'
  $__tbot_v3_py   = 'C:\alpaca-bot\ORG_BOT_UNIFIED\code\.venv\Scripts\python.exe'
  $__tbot_v3_log  = 'C:\alpaca-bot\ORG_BOT_UNIFIED\runtime\paper\logs\hardening_events.jsonl'

  $__tbot_v3_cmd = ""
  try {
    $__tbot_v3_cmd = (
      Get-CimInstance Win32_Process -Filter ("ProcessId=" + $PID) -ErrorAction Stop
    ).CommandLine
  } catch {
    $__tbot_v3_cmd = ""
  }

  $__tbot_v3_scriptPath = ($PSCommandPath -as [string])
  $__tbot_v3_pwdPath    = ((Get-Location).Path -as [string])
  $__tbot_v3_pythonpath = ($env:PYTHONPATH -as [string])
  $__tbot_v3_runroot    = ($env:TBOT_RUNROOT -as [string])

  $__tbot_v3_root_exists   = (Test-Path $__tbot_v3_root)
  $__tbot_v3_python_exists = (Test-Path $__tbot_v3_py)

  $__tbot_v3_script_under_unified   = [bool]($__tbot_v3_scriptPath -like "*ORG_BOT_UNIFIED*")
  $__tbot_v3_pwd_under_unified      = [bool]($__tbot_v3_pwdPath -like "*ORG_BOT_UNIFIED*")
  $__tbot_v3_pythonpath_has_unified = [bool]($__tbot_v3_pythonpath -like "*ORG_BOT_UNIFIED*")
  $__tbot_v3_runroot_has_unified    = [bool]($__tbot_v3_runroot -like "*ORG_BOT_UNIFIED*")

  $__tbot_v3_reasons = New-Object System.Collections.Generic.List[string]

  if (-not $__tbot_v3_root_exists)   { [void]$__tbot_v3_reasons.Add("canonical_root_missing") }
  if (-not $__tbot_v3_python_exists) { [void]$__tbot_v3_reasons.Add("canonical_python_missing") }
  if (-not $__tbot_v3_script_under_unified)   { [void]$__tbot_v3_reasons.Add("script_not_under_unified") }
  if (-not $__tbot_v3_pwd_under_unified)      { [void]$__tbot_v3_reasons.Add("pwd_not_under_unified") }
  if (-not $__tbot_v3_pythonpath_has_unified) { [void]$__tbot_v3_reasons.Add("pythonpath_not_under_unified") }
  if (-not $__tbot_v3_runroot_has_unified)    { [void]$__tbot_v3_reasons.Add("runroot_not_under_unified") }

  $__tbot_v3_guard_status = if ($__tbot_v3_reasons.Count -eq 0) { "PASS" } else { "WARN" }

  $__tbot_v3_row = [ordered]@{
    ts                      = (Get-Date).ToString("s")
    kind                    = "wrapper_guard_status_v3"
    wrapper                 = "ORG_UNIFIED_RUNTIME_MANAGER.ps1"
    canonical_root          = $__tbot_v3_root
    canonical_root_exists   = $__tbot_v3_root_exists
    canonical_python        = $__tbot_v3_py
    canonical_python_exists = $__tbot_v3_python_exists
    current_script          = $__tbot_v3_scriptPath
    current_location        = $__tbot_v3_pwdPath
    env_pythonpath          = $__tbot_v3_pythonpath
    env_tbot_runroot        = $__tbot_v3_runroot
    process_commandline     = $__tbot_v3_cmd
    script_under_unified    = $__tbot_v3_script_under_unified
    pwd_under_unified       = $__tbot_v3_pwd_under_unified
    pythonpath_has_unified  = $__tbot_v3_pythonpath_has_unified
    runroot_has_unified     = $__tbot_v3_runroot_has_unified
    guard_status            = $__tbot_v3_guard_status
    guard_reasons           = @($__tbot_v3_reasons)
  }

  $__tbot_v3_dir = Split-Path -Parent $__tbot_v3_log
  if ($__tbot_v3_dir) {
    New-Item -ItemType Directory -Force -Path $__tbot_v3_dir | Out-Null
  }

  ($__tbot_v3_row | ConvertTo-Json -Compress -Depth 10) |
    Add-Content -LiteralPath $__tbot_v3_log -Encoding UTF8
} catch {
  # best-effort only
}
# PATCH_V3_GUARD_STATUS_END
